"""Static and subprocess-based checks for Python generated by language models."""

from __future__ import annotations

import ast
import builtins
import re
import subprocess
import sys
import time
from dataclasses import dataclass, field
from typing import Iterable

from .models import AuditIssue

_FENCE_RE = re.compile(r"```(?:python|py)\s*\n?(.*?)```", re.IGNORECASE | re.DOTALL)
_DANGEROUS_MODULES = {
    "subprocess",
    "os",
    "socket",
    "shutil",
    "ctypes",
    "pathlib",
}
_DANGEROUS_CALLS = {
    "eval",
    "exec",
    "__import__",
    "compile",
    "system",
    "popen",
    "run",
    "call",
    "check_call",
    "check_output",
    "rmtree",
    "remove",
    "unlink",
}


@dataclass(slots=True)
class CodeAuditResult:
    """Results from static inspection and optional test execution."""

    code_blocks: list[str] = field(default_factory=list)
    issues: list[AuditIssue] = field(default_factory=list)
    syntax_ok: bool = False
    safe_to_execute: bool = False
    executed: bool = False
    passed: bool = False
    stdout: str = ""
    stderr: str = ""
    execution_time_ms: float = 0.0

    @property
    def tests_passed(self) -> bool:
        """Expose pass status using an explicit test-oriented name."""
        return self.passed


class _NameCollector(ast.NodeVisitor):
    def __init__(self) -> None:
        self.bound: set[str] = set()
        self.loaded: list[ast.Name] = []

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load):
            self.loaded.append(node)
        else:
            self.bound.add(node.id)
        self.generic_visit(node)

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self.bound.add(alias.asname or alias.name.split(".")[0])

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        for alias in node.names:
            self.bound.add(alias.asname or alias.name)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self.bound.add(node.name)
        for argument in (*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs):
            self.bound.add(argument.arg)
        if node.args.vararg:
            self.bound.add(node.args.vararg.arg)
        if node.args.kwarg:
            self.bound.add(node.args.kwarg.arg)
        self.generic_visit(node)

    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        self.bound.add(node.name)
        self.generic_visit(node)


class PythonCodeVerifier:
    """Inspect fenced Python and run approved snippets in a child process."""

    def __init__(self, timeout_seconds: float = 2.0) -> None:
        if timeout_seconds <= 0:
            raise ValueError("timeout_seconds must be positive")
        self.timeout_seconds = timeout_seconds

    @staticmethod
    def extract_code_blocks(response: str) -> list[str]:
        """Extract Python fenced blocks or code-shaped unfenced text."""
        blocks = [block.strip() for block in _FENCE_RE.findall(response) if block.strip()]
        if blocks:
            return blocks
        text = response.strip()
        code_markers = ("def ", "class ", "import ", "from ", "return ", "assert ", "while ", "for ")
        return [text] if text and any(marker in text for marker in code_markers) else []

    def inspect(self, response: str) -> CodeAuditResult:
        """Parse code and report syntax, safety, and unresolved-name findings."""
        result = CodeAuditResult(code_blocks=self.extract_code_blocks(response))
        if not result.code_blocks:
            result.syntax_ok = True
            result.safe_to_execute = True
            return result

        trees: list[ast.AST] = []
        for block_index, block in enumerate(result.code_blocks, start=1):
            try:
                trees.append(ast.parse(block))
            except SyntaxError as exc:
                result.issues.append(
                    AuditIssue(
                        severity="error",
                        category="syntax",
                        message=f"Python block {block_index} has a syntax error: {exc.msg}.",
                        line=exc.lineno,
                    )
                )
        result.syntax_ok = len(trees) == len(result.code_blocks)
        if not result.syntax_ok:
            return result

        for tree in trees:
            result.issues.extend(self._static_issues(tree))
        result.safe_to_execute = not any(
            issue.severity in {"error", "critical"} for issue in result.issues
        )
        return result

    def verify(
        self,
        response: str,
        test_assertions: Iterable[str] = (),
    ) -> CodeAuditResult:
        """Inspect code, then run assertions in a timeout-bounded child process."""
        result = self.inspect(response)
        assertions = [assertion.strip() for assertion in test_assertions if assertion.strip()]
        if not result.code_blocks or not result.safe_to_execute:
            result.passed = result.safe_to_execute and not assertions
            return result

        source = "\n\n".join(result.code_blocks)
        test_code = "\n".join(assertions)
        script = (
            "import contextlib, io\n"
            f"SOURCE = {source!r}\n"
            f"TESTS = {test_code!r}\n"
            "stdout = io.StringIO()\n"
            "stderr = io.StringIO()\n"
            "namespace = {'__name__': '__main__'}\n"
            "with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):\n"
            "    exec(compile(SOURCE, '<generated>', 'exec'), namespace)\n"
            "    exec(compile(TESTS, '<assertions>', 'exec'), namespace)\n"
            "print(stdout.getvalue(), end='')\n"
            "print(stderr.getvalue(), end='', file=__import__('sys').stderr)\n"
        )
        start = time.perf_counter()
        try:
            completed = subprocess.run(
                [sys.executable, "-I", "-c", script],
                input=None,
                capture_output=True,
                text=True,
                timeout=self.timeout_seconds,
                check=False,
                env={},
            )
        except subprocess.TimeoutExpired as exc:
            result.execution_time_ms = round((time.perf_counter() - start) * 1000, 3)
            result.executed = True
            result.stderr = "Execution timed out."
            result.issues.append(
                AuditIssue(
                    severity="error",
                    category="timeout",
                    message=f"Execution exceeded {self.timeout_seconds:.2f} seconds.",
                )
            )
            return result

        result.execution_time_ms = round((time.perf_counter() - start) * 1000, 3)
        result.executed = True
        result.stdout = completed.stdout
        result.stderr = completed.stderr
        result.passed = completed.returncode == 0
        if not result.passed:
            result.issues.append(
                AuditIssue(
                    severity="error",
                    category="execution",
                    message="Generated code or an assertion failed during execution.",
                    evidence=completed.stderr[-500:] or completed.stdout[-500:],
                )
            )
        return result

    def _static_issues(self, tree: ast.AST) -> list[AuditIssue]:
        issues: list[AuditIssue] = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    module = alias.name.split(".")[0]
                    if module in _DANGEROUS_MODULES:
                        issues.append(
                            AuditIssue(
                                severity="critical",
                                category="dangerous_import",
                                message=f"Import of '{alias.name}' is blocked.",
                                line=node.lineno,
                            )
                        )
            elif isinstance(node, ast.ImportFrom):
                module = (node.module or "").split(".")[0]
                if module in _DANGEROUS_MODULES:
                    issues.append(
                        AuditIssue(
                            severity="critical",
                            category="dangerous_import",
                            message=f"Import from '{node.module}' is blocked.",
                            line=node.lineno,
                        )
                    )
            elif isinstance(node, ast.Call):
                name = self._call_name(node.func)
                if name and (name.split(".")[0] in _DANGEROUS_MODULES or name in _DANGEROUS_CALLS):
                    issues.append(
                        AuditIssue(
                            severity="critical",
                            category="dangerous_call",
                            message=f"Call to '{name}' is blocked.",
                            line=node.lineno,
                        )
                    )

        collector = _NameCollector()
        collector.visit(tree)
        known = set(dir(builtins)) | collector.bound
        for node in collector.loaded:
            if node.id not in known and not node.id.startswith("_"):
                issues.append(
                    AuditIssue(
                        severity="warning",
                        category="undefined_name",
                        message=f"Name '{node.id}' is used before a local definition.",
                        line=node.lineno,
                    )
                )
        return issues

    @staticmethod
    def _call_name(node: ast.AST) -> str | None:
        parts: list[str] = []
        current = node
        while isinstance(current, ast.Attribute):
            parts.append(current.attr)
            current = current.value
        if isinstance(current, ast.Name):
            parts.append(current.id)
            return ".".join(reversed(parts))
        if isinstance(node, ast.Name):
            return node.id
        return None
